//! Turning generated tokens into formatted source.

use proc_macro2::TokenStream;

/// Formats generated items with prettyplease and adds the file header.
///
/// `#[comment = "..."]` attributes come out as `//` comments.
pub(crate) fn render(tokens: TokenStream) -> String {
    let file: syn::File = syn::parse2(tokens).unwrap_or_else(|error| {
        panic!("imping-codegen generated invalid Rust ({error}); this is a bug")
    });
    let mut source = format!(
        "// Generated by imping-codegen {}. Do not edit.\n\n",
        env!("CARGO_PKG_VERSION")
    );
    source.push_str(&separate_items(&prettyplease::unparse(&file)));
    source
}

/// Inserts a blank line between consecutive items, which prettyplease runs
/// together inside modules and impls.
///
/// A line starts a new item when it is indented like the previous line and
/// that line closed a block or a multi-line item (`}`, `};` or `);`) or was a
/// one-line item (a type alias, tuple struct, static or assertion).
fn separate_items(source: &str) -> String {
    let mut out = String::with_capacity(source.len() + source.len() / 16);
    let mut previous: Option<&str> = None;
    for line in source.lines() {
        if let Some(previous) = previous {
            let trimmed = previous.trim();
            let one_line_item = trimmed.ends_with(';')
                && ["pub type ", "pub struct ", "pub static ", "const _: () ="]
                    .iter()
                    .any(|start| trimmed.starts_with(start));
            let ends_item = matches!(trimmed, "}" | "};" | ");") || one_line_item;
            let current = line.trim();
            if ends_item
                && indent(previous) == indent(line)
                && !current.is_empty()
                && !current.starts_with('}')
            {
                out.push('\n');
            }
        }
        out.push_str(line);
        out.push('\n');
        previous = Some(line);
    }
    out
}

fn indent(line: &str) -> usize {
    line.len() - line.trim_start().len()
}

#[cfg(test)]
mod tests {
    use super::separate_items;

    #[test]
    fn separates_items_but_not_statements_or_closing_braces() {
        let input = "mod m {\n    pub struct A {}\n    impl A {\n        fn f() {}\n        fn g() {\n            x;\n        }\n        fn h() {}\n    }\n    pub type B = u8;\n    pub struct C(pub u8);\n    pub static D: u8 = f(\n        1,\n    );\n    const _: () = {\n        a;\n        b;\n    };\n    const E: u8 = 1;\n    const F: u8 = 2;\n}\n";
        let expected = "mod m {\n    pub struct A {}\n    impl A {\n        fn f() {}\n        fn g() {\n            x;\n        }\n\n        fn h() {}\n    }\n\n    pub type B = u8;\n\n    pub struct C(pub u8);\n\n    pub static D: u8 = f(\n        1,\n    );\n\n    const _: () = {\n        a;\n        b;\n    };\n\n    const E: u8 = 1;\n    const F: u8 = 2;\n}\n";
        assert_eq!(separate_items(input), expected);
    }
}
